# 4. Review by class (expected open: 262).
python - "$DATA" <<'PY'
import sys

import duckdb

con = duckdb.connect(f"{sys.argv[1]}/market.duckdb", read_only=True)
for row in con.execute(
    """SELECT coalesce(json_extract_string(details, '$.class'), '-') AS cls,
              coalesce(json_extract_string(details, '$.subclass'), '-') AS sub, count(*) AS findings,
              count(DISTINCT entity_id) AS entities
       FROM quarantine_queue WHERE resolved_at IS NULL AND reason_code = 'ANNUAL_PRIOR_YEAR_DIFFERS'
       GROUP BY ALL ORDER BY ALL"""
).fetchall():
    print(row)
PY

# 5. The rescale corrections mark their entities dirty: materialize the affected rows.
$F materialize --incremental
